import math
from itertools import islice

def sieve_of_eratosthenes(limit):
    """Generate all primes up to limit using Sieve of Eratosthenes."""
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False

    return [i for i in range(2, limit + 1) if is_prime[i]]

def get_primes_in_range(m, n):
    """Get all primes in the range [m, n] using precomputed primes."""
    # Since n can be up to 10^9, we can't generate all primes up to n directly
    # Instead, we use the fact that n - m <= 100000, so we can generate primes up to sqrt(n)
    # and then use segmented sieve for the range [m, n]

    if n < 2:
        return []

    # Generate all primes up to sqrt(n)
    sqrt_n = int(math.sqrt(n)) + 1
    base_primes = sieve_of_eratosthenes(sqrt_n)

    # Use segmented sieve to find primes in [m, n]
    size = n - m + 1
    is_prime_in_range = [True] * size

    # Mark multiples of each base prime in [m, n]
    for prime in base_primes:
        # Find the first multiple of prime >= m
        start = ((m + prime - 1) // prime) * prime
        if start < m:
            start += prime

        # Mark all multiples of prime in [m, n]
        for j in range(start, n + 1, prime):
            is_prime_in_range[j - m] = False

    # Collect all primes in the range
    result = []
    for i in range(m, n + 1):
        if is_prime_in_range[i - m]:
            result.append(i)

    return result

def main():
    t = int(input())

    for case_num in range(t):
        m, n = map(int, input().split())

        primes = get_primes_in_range(m, n)

        for p in primes:
            print(p)

        # Print empty line between test cases (except after the last one)
        if case_num < t - 1:
            print()

if __name__ == "__main__":
    main()
